// org.site.setDeviceAlerts — E4 (Vlad, 3 Nov): link to the mall, alerts checkbox. Generated by
// `pnpm gen:command`; guard cases kept, acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  grantOf,
  NotFound,
  openTestKernel,
  RuleViolation,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient } from '../commands/create-client.ts';
import { createSite } from '../commands/create-site.ts';
import { setDeviceAlerts } from '../commands/set-device-alerts.ts';
import { siteList } from '../queries/site-list.ts';

const pm = aStaffActor({ roles: ['pm'] });
const other = aStaffActor({ roles: ['finance'] });
const audited = async () => countRows(testDb.url, 'audit_event WHERE command = $1', [setDeviceAlerts.name]);
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
let siteB: string;
const set = (siteId: string, platformRef: string | null, alertsEnabled: boolean) =>
  t.kernel.execute(setDeviceAlerts, pm, { siteId, platformRef, alertsEnabled }, 'test');

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(pm, setDeviceAlerts.permission, siteList.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Mall', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  ({ id: siteB } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('org.site.setDeviceAlerts', () => {
  it('is for directors and PMs; refuses others, bad input and an unknown project, recording nothing', async () => {
    expect(grantOf(setDeviceAlerts.permission)?.roles).toEqual(['director', 'pm']);
    await expect(
      t.kernel.execute(
        setDeviceAlerts,
        other,
        { siteId: siteA, platformRef: 'mall-a', alertsEnabled: true },
        'test',
      ),
    ).rejects.toBeInstanceOf(Forbidden);
    await expect(set(siteA, ' ', false)).rejects.toBeInstanceOf(ValidationFailed);
    await expect(set(randomUUID(), 'mall-a', false)).rejects.toBeInstanceOf(NotFound);
    expect(await audited()).toBe(0);
  });

  it('alerts need a linked mall', async () => {
    await expect(set(siteA, null, true)).rejects.toBeInstanceOf(RuleViolation);
  });

  it('links the mall, ticks the box, and the staff site list shows both; audited', async () => {
    expect(await set(siteA, 'mall-a', true)).toEqual({ platformRef: 'mall-a', deviceAlertsEnabled: true });
    const sites = await t.kernel.read(siteList, pm, {});
    expect(sites.find((s) => s.id === siteA)).toMatchObject({
      platformRef: 'mall-a',
      deviceAlertsEnabled: true,
    });
    expect(await audited()).toBe(1);
  });

  it('one mall belongs to one project; unticking and unlinking work', async () => {
    await expect(set(siteB, 'mall-a', false)).rejects.toBeInstanceOf(Conflict);
    expect(await set(siteA, 'mall-a', false)).toEqual({ platformRef: 'mall-a', deviceAlertsEnabled: false });
    expect(await set(siteA, null, false)).toEqual({ platformRef: null, deviceAlertsEnabled: false });
    await set(siteB, 'mall-a', false);
  });
});
